5	  ax === bx && ay === by;
6	
7	/** Two cells are neighbours when they touch on any side or corner. */
8	const isNeighbour = (candidate: Cell, cell: Cell): boolean =>
9	  Math.abs(candidate[0] - cell[0]) <= 1 &&
10	  Math.abs(candidate[1] - cell[1]) <= 1 &&
11	  !isSameCell(candidate, cell);
12	
13	const countLiveNeighbours = (cell: Cell, liveCells: Cell[]): number =>
14	  liveCells.filter((candidate) => isNeighbour(candidate, cell)).length;
15	
16	/** Rule 1 & 2 & 3: a live cell survives with exactly 2 or 3 live neighbours. */
17	const survives = (liveNeighbours: number): boolean =>
18	  liveNeighbours === 2 || liveNeighbours === 3;
19	
20	export function nextGeneration(liveCells: Cell[]): Cell[] {
21	  return liveCells.filter((cell) =>
22	    survives(countLiveNeighbours(cell, liveCells)),
