const neighbourhoodOf = ([x, y]: Cell): Cell[] => {
  const cells: Cell[] = [];
  for (const dx of [-1, 0, 1]) {
    for (const dy of [-1, 0, 1]) {
      if (dx !== 0 || dy !== 0) cells.push([x + dx, y + dy]);
    }
  }
  return cells;
};

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) =>
    survives(countLiveNeighbours(cell, liveCells)),
  );

  const births = liveCells
    .flatMap(neighbourhoodOf)
    .filter(
      (candidate) =>
        !liveCells.some((live) => isSameCell(live, candidate)) &&
        countLiveNeighbours(candidate, liveCells) === 3,
    );

  const uniqueBirths = births.filter(
    (cell, index) =>
      births.findIndex((other) => isSameCell(other, cell)) === index,
  );

  return [...survivors, ...uniqueBirths];
}

